"""IMP2-17/18: generated bytes, explicit mapping and complete import coverage."""
import copy
import hashlib
from pathlib import Path
import tempfile
import unittest
import xml.etree.ElementTree as ET

from clxreg import export, ledger, sources
from tests import ledger_forgery as forge
from tests.test_ledger import Fx
from tests.test_units import ods, row, cell, p

H = '227733484a1851bc512f7ba3fef6dd78b6d0e5da'


def model():
    return {'schema': 'model/1', 'records': [
        {'id': 'CLX-REQ-0002', 'type': 'REQ', 'title': 'unknown', 'asserted_status': [{'status': 'DONE'}]},
        {'id': 'CLX-REQ-0001', 'type': 'REQ', 'title': 'a  b\tc\nd <e>'}],
        'derived': {'CLX-REQ-0002': {'verification': 'UNKNOWN', 'effective_status': 'UNKNOWN'},
                    'CLX-REQ-0001': {'verification': 'VERIFIED', 'effective_status': 'DONE'}},
        'findings': [], 'valid': True, 'examined': 2, 'rule_counts': {}}


class ViewTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)

    def test_repeat_and_record_order_have_identical_bytes(self):
        original = model()
        reordered = copy.deepcopy(original)
        reordered['records'].reverse()
        one = export.tables(original, registry_commit=H)
        two = export.tables(reordered, registry_commit=H)
        self.assertEqual(export.tsv(one), export.tsv(two))
        self.assertEqual(export.fods(one), export.fods(two))
        self.assertEqual(export.fods(one), export.fods(one))
        self.assertEqual(original, model())
        self.assertIn(['registry_commit_role', 'reference baseline; clean-tree binding not asserted'], one['REGISTRY-METADATA'])
        digest = next(r[1] for r in one['REGISTRY-METADATA'] if r[0] == 'registry_records_sha256')
        self.assertEqual(len(digest), 64)
        changed = model()
        changed['records'][0]['title'] = 'different saved registry content'
        changed_meta = export.tables(changed, registry_commit=H)['REGISTRY-METADATA']
        self.assertNotEqual(digest, next(r[1] for r in changed_meta if r[0] == 'registry_records_sha256'))

    def test_fods_xml_uses_string_cells_and_preserves_literal_whitespace(self):
        data = export.fods(export.tables(model(), registry_commit=H))
        root = ET.fromstring(data)
        self.assertEqual(root.tag, '{'+export.OFFICE+'}document')
        self.assertTrue(root.findall('.//{'+export.TEXT+'}s'))
        self.assertTrue(root.findall('.//{'+export.TEXT+'}tab'))
        self.assertTrue(root.findall('.//{'+export.TEXT+'}line-break'))
        self.assertNotIn(b'table:formula', data)
        self.assertIn(b'&lt;e&gt;', data)

    def test_formula_like_values_are_literal_and_carriage_return_is_preserved(self):
        data = export.fods({'literal': [['=SUM(A1:A2)', 'a\rb']]})
        parsed = ET.fromstring(data)
        cells = parsed.findall('.//{'+export.TABLE+'}table-cell')
        self.assertTrue(all(c.get('{'+export.OFFICE+'}value-type') == 'string' for c in cells))
        self.assertEqual(cells[0].find('{'+export.TEXT+'}p').text, '=SUM(A1:A2)')
        self.assertEqual(cells[1].find('{'+export.TEXT+'}p').text, 'a\rb')
        self.assertNotIn(b'formula=', data)
        with self.assertRaises(export.ExportError):
            export.fods({'bad': [['nul\x00char']]})

    def test_explicit_ods_row_mapping_input_hash_is_unchanged(self):
        path = self.root / 'source.ods'
        path.write_bytes(ods({'Plan': row(cell(p('RT1')), cell(p('DONE')))}))
        before = path.read_bytes()
        mapping = {'schema': 'clx.roadmap-mapping/1', 'rows': [{'record': 'CLX-REQ-0001', 'sheet': 'Plan', 'row_id': 'RT1'}]}
        tables = export.tables(model(), registry_commit=H, mapping=mapping, ods_path=path)
        self.assertEqual(tables['REGISTRY-ROADMAP'][1][-3:], ['Plan', 'RT1', '1'])
        self.assertEqual(tables['REGISTRY-EXPORT-FINDINGS'], [['record', 'message', 'sheet', 'row_id']])
        self.assertEqual(path.read_bytes(), before)
        self.assertIn(['ODS sha256', hashlib.sha256(before).hexdigest()], tables['REGISTRY-METADATA'])

    def test_absent_and_ambiguous_ods_rows_are_named_without_guessing(self):
        path = self.root / 'source.ods'
        path.write_bytes(ods({'Plan': row(cell(p('RT1'))) + row(cell(p('RT1')))}))
        mapping = {'schema': 'clx.roadmap-mapping/1', 'rows': [
            {'record': 'CLX-REQ-0001', 'sheet': 'Plan', 'row_id': 'RT1'},
            {'record': 'CLX-REQ-0002', 'sheet': 'Plan', 'row_id': 'RT2'}]}
        tables = export.tables(model(), registry_commit=H, mapping=mapping, ods_path=path)
        self.assertEqual([r[1] for r in tables['REGISTRY-EXPORT-FINDINGS'][1:]], ['ODS row id is ambiguous', 'ODS row not found'])
        self.assertEqual([r[-1] for r in tables['REGISTRY-ROADMAP'][1:]], ['', ''])

    def test_claim_done_is_displayed_beside_unknown_with_drift(self):
        r = export.tables(model(), registry_commit=H)['REGISTRY-ROADMAP'][2]
        self.assertEqual(r[3:7], ['UNKNOWN', 'UNKNOWN', 'DONE', 'CLAIM_DIFFERS'])

    def test_refuses_overwrite_for_both_formats(self):
        for extension in ('tsv', 'fods'):
            path = self.root / ('view.'+extension)
            export.write(path, model(), registry_commit=H)
            before = path.read_bytes()
            with self.assertRaises(FileExistsError):
                export.write(path, model(), registry_commit=H)
            self.assertEqual(path.read_bytes(), before)

    def test_bad_model_commit_or_mapping_is_not_silently_exported(self):
        for bad in ('', '2277334', None):
            with self.assertRaises(export.ExportError):
                export.tables(model(), registry_commit=bad)
        with self.assertRaises(export.ExportError):
            export.tables({'schema': 'model/2'}, registry_commit=H)
        with self.assertRaises(export.ExportError):
            export.tables({**model(), 'schema': 'model/2'}, registry_commit=H)
        with self.assertRaises(export.ExportError):
            export.tables(model(), registry_commit=H, mapping={'schema': 'bad'})
        with self.assertRaises(export.ExportError):
            export.tables(model(), registry_commit=H, mapping={'schema': 'clx.roadmap-mapping/1', 'rows': []})


class CoverageTests(Fx):
    def test_every_disposition_occurrence_has_summary_and_literal_detail(self):
        led = self.build()
        tables = export.tables(model(), registry_commit=H, import_ledger=led)
        summary = tables['REGISTRY-COVERAGE-OF-IMPORT'][1:]
        detail = tables['REGISTRY-IMPORT-OCCURRENCES'][1:]
        self.assertEqual(sum(int(r[-1]) for r in summary), len(led['entries']))
        self.assertEqual(len(detail), len(led['entries']))
        self.assertEqual(sorted(r[5] for r in detail), sorted(e['text'] for e in led['entries']))
        self.assertIn('AMBIGUOUS', {r[2] for r in summary})
        self.assertIn('RANGE_NOT_EXPANDED', {r[2] for r in summary})
        self.assertTrue(next(r[1] for r in tables['REGISTRY-METADATA'] if r[0] == 'import_ledger_sha256'))

    def test_ledger_changes_alter_the_view_and_summary_is_checked(self):
        before = self.build()
        (self.ws / 'a.md').write_bytes(b'RT1 RT1 RT1 RT1\n')
        self.src['sources'][0]['versions'][0].update(sha256=hashlib.sha256(b'RT1 RT1 RT1 RT1\n').hexdigest(), bytes=16)
        # Build a valid new ledger from the changed explicitly pinned source.
        self.src['sources'][0]['versions'][0]['bytes'] = len((self.ws / 'a.md').read_bytes())
        after = self.build()
        self.assertNotEqual(export.tsv(export.tables(model(), registry_commit=H, import_ledger=before)), export.tsv(export.tables(model(), registry_commit=H, import_ledger=after)))
        after['summary']['entries'] += 1
        with self.assertRaises(export.ExportError):
            export.tables(model(), registry_commit=H, import_ledger=after)


class LedgerTrustTests(unittest.TestCase):
    LEGACY_METADATA = ['key', 'schema version', 'registry commit', 'registry_commit_role', 'registry_records_sha256', 'import_ledger_sha256', 'ODS sha256', 'ledger occurrences']
    ROWS = ['import_ledger_verification', 'import_ledger_rebuild_inputs', 'import_ledger_complete', 'import_ledger_problems', 'import_ledger_sources_not_processed', 'import_ledger_problem_details', 'import_ledger_source_details']
    FORGED = (('K1', forge.WITH_RT2, None, forge.k1_processed_to_excluded),
              ('K2', forge.WITH_RT2, None, forge.k2_drop_rt2),
              ('K3', forge.CLEAN, None, forge.k3_problem_without_problems),
              ('K4', forge.CLEAN, None, forge.k4_processed_to_missing),
              ('K5', forge.CLEAN, None, forge.k5_fabricated_alias),
              ('K6', forge.CLEAN, forge.AMBIGUOUS_RT1, forge.k6_erase_ambiguity),
              ('K7', forge.WITH_RT2, None, forge.k7_omit_source))

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.count = 0

    def scenario(self, second=forge.CLEAN, ambiguity=None):
        self.count += 1
        directory = Path(self.tmp.name) / str(self.count)
        directory.mkdir()
        return forge.Scenario(directory, second, ambiguity)

    def meta(self, led=None, inputs=None):
        return dict(export.tables(model(), registry_commit=H, import_ledger=led, ledger_inputs=inputs)['REGISTRY-METADATA'])

    def test_new_rows_follow_the_existing_ones_and_are_empty_without_a_ledger(self):
        rows = export.tables(model(), registry_commit=H)['REGISTRY-METADATA']
        self.assertEqual([r[0] for r in rows], self.LEGACY_METADATA + self.ROWS)
        self.assertEqual([r[1] for r in rows[-len(self.ROWS):]], [''] * len(self.ROWS))

    def test_ledger_alone_is_labelled_not_verified(self):
        s = self.scenario()
        meta = self.meta(s.honest())
        self.assertEqual(meta['import_ledger_verification'], 'NOT_VERIFIED')
        self.assertEqual(meta['import_ledger_rebuild_inputs'], '')
        self.assertEqual((meta['import_ledger_complete'], meta['import_ledger_problems'], meta['import_ledger_sources_not_processed']), ('true', '0', ''))

    def test_honest_ledger_with_trusted_inputs_is_rebuild_matched(self):
        s = self.scenario(ambiguity=forge.AMBIGUOUS_RT1)
        led = s.honest()
        meta = self.meta(led, s.export_inputs())
        self.assertEqual(meta['import_ledger_verification'], 'REBUILD_MATCHED')
        self.assertIn('run=' + led['inputs']['run_digest'], meta['import_ledger_rebuild_inputs'])
        self.assertIn('ambiguity=' + led['inputs']['ambiguity_digest'], meta['import_ledger_rebuild_inputs'])
        self.assertIn('mapping=none', meta['import_ledger_rebuild_inputs'])

    def test_both_modes_reach_both_output_formats(self):
        s = self.scenario()
        for inputs, label in ((None, b'NOT_VERIFIED'), (s.export_inputs(), b'REBUILD_MATCHED')):
            for extension in ('tsv', 'fods'):
                path = Path(self.tmp.name) / (label.decode() + '.' + extension)
                result = export.write(path, model(), registry_commit=H, import_ledger=s.honest(), ledger_inputs=inputs)
                self.assertEqual(result['import_ledger_verification'], label.decode())
                self.assertIn(label, path.read_bytes())

    def test_forgeries_are_refused_with_trusted_inputs_and_nothing_is_written(self):
        for name, second, ambiguity, forgery in self.FORGED:
            s = self.scenario(second, ambiguity)
            forged = forgery(s.honest())
            if name == 'K3':
                self.assertTrue(ledger.validate_ledger(forged))
            else:
                self.assertEqual(ledger.validate_ledger(forged), [], name)
            path = Path(self.tmp.name) / (name + '.tsv')
            with self.subTest(name):
                with self.assertRaises(export.ExportError if name == 'K3' else ledger.RebuildMismatch):
                    export.write(path, model(), registry_commit=H, import_ledger=forged, ledger_inputs=s.export_inputs())
                self.assertFalse(path.exists())

    def test_forgeries_without_trusted_inputs_are_never_called_verified(self):
        for name, second, ambiguity, forgery in self.FORGED:
            s = self.scenario(second, ambiguity)
            with self.subTest(name):
                if name == 'K3':
                    with self.assertRaises(export.ExportError):
                        self.meta(forgery(s.honest()))
                else:
                    self.assertEqual(self.meta(forgery(s.honest()))['import_ledger_verification'], 'NOT_VERIFIED')

    def test_forged_non_processed_sources_stay_visible_without_trusted_inputs(self):
        s = self.scenario()
        cases = ((forge.k1_processed_to_excluded, 'doc/v2=EXCLUDED', 'true'), (forge.k4_processed_to_missing, 'doc/v2=MISSING', 'false'))
        for forgery, row, complete in cases:
            with self.subTest(row):
                meta = self.meta(forgery(s.honest()))
                self.assertEqual((meta['import_ledger_sources_not_processed'], meta['import_ledger_complete']), (row, complete))

    def test_honest_incomplete_ledgers_are_exported_truthfully(self):
        s = self.scenario()
        (s.ws / 'b.md').unlink()
        meta = self.meta(s.honest(), s.export_inputs())
        self.assertEqual(meta['import_ledger_verification'], 'REBUILD_MATCHED')
        self.assertEqual((meta['import_ledger_complete'], meta['import_ledger_problems'], meta['import_ledger_sources_not_processed']), ('false', '0', 'doc/v2=MISSING'))
        s = self.scenario()
        (s.ws / 'b.md').write_bytes(b'changed\n')
        meta = self.meta(s.honest(), s.export_inputs())
        self.assertEqual((meta['import_ledger_complete'], meta['import_ledger_problems'], meta['import_ledger_sources_not_processed']), ('false', '1', 'doc/v2=PROBLEM'))

    def test_unavailable_source_is_not_reported_as_a_forgery(self):
        s = self.scenario()
        led = s.honest()
        (s.ws / 'b.md').unlink()
        path = Path(self.tmp.name) / 'out.tsv'
        with self.assertRaises(sources.SourceError):
            export.write(path, model(), registry_commit=H, import_ledger=led, ledger_inputs=s.export_inputs())
        self.assertFalse(path.exists())

    def test_unusable_verification_inputs_are_export_errors(self):
        s = self.scenario()
        led = s.honest()
        good = s.export_inputs()
        without = {k: v for k, v in good.items() if k != 'ambiguity'}
        for name, inputs in (('omitted ambiguity', without), ('not a dict', ['run']), ('extra', {**good, 'x': 1}), ('no run', {**good, 'run': None}), ('no catalog', {**good, 'catalog': None}), ('no namespaces', {**good, 'namespaces': None}), ('no roots', {**good, 'roots': None}), ('invalid run', {**good, 'run': {'schema': 'bad'}})):
            with self.subTest(name), self.assertRaises(export.ExportError):
                self.meta(led, inputs)
        with self.assertRaises(export.ExportError):
            self.meta(None, good)

    def test_refused_export_leaves_an_existing_output_untouched(self):
        s = self.scenario(forge.WITH_RT2)
        path = Path(self.tmp.name) / 'kept.tsv'
        path.write_bytes(b'kept')
        with self.assertRaises(FileExistsError):
            export.write(path, model(), registry_commit=H, import_ledger=forge.k2_drop_rt2(s.honest()), ledger_inputs=s.export_inputs())
        self.assertEqual(path.read_bytes(), b'kept')


if __name__ == '__main__':
    unittest.main()
